    private fun lesson017() = Lesson(
        id = "mit_18_06sc_2011_s017",
        title = "Projeter sur une droite ou un sous-espace",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_18_06sc_2011_s017_e01", prompt = "Projeter b=(2,0) sur la droite engendrée par a=(1,1).", options = listOf("(2,0)", "(0,0)", "(1,1)", "(2,2)"), correctOptionIndex = 2, explanation = "Le coefficient est (aᵀb)/(aᵀa)=2/2=1 ; la projection est donc a.", hint = "Diviser le produit scalaire par la norme au carré."),
            Exercise.MathChallenge(id = "mit_18_06sc_2011_s017_e02", prompt = "Quelle matrice projette orthogonalement sur la droite y=x ?", options = listOf("[[1,0],[0,0]]", "[[1/2,1/2],[1/2,1/2]]", "[[1,1],[1,1]]", "[[1/2,0],[0,1/2]]"), correctOptionIndex = 1, explanation = "Avec a=(1,1), aaᵀ contient quatre 1 et aᵀa=2 ; diviser donne P.", hint = "Construire le produit extérieur puis normaliser."),
            Exercise.MultipleChoice(id = "mit_18_06sc_2011_s017_e03", prompt = "Si b appartient déjà au sous-espace de projection, que vaut Pb ?", options = listOf("b", "0", "2b", "Une valeur nécessairement différente de b."), correctOptionIndex = 0, explanation = "Le point du sous-espace le plus proche de b est b lui-même, avec résidu nul.", hint = "La distance minimale peut-elle être plus petite que zéro ?")
        ),
        objective = "Calculer le point le plus proche et son résidu orthogonal.",
        learningNotes = "Pour projeter b sur la droite engendrée par a≠0, chercher p=ca et imposer aᵀ(b−ca)=0. On obtient c=(aᵀb)/(aᵀa), puis p=a(aᵀb)/(aᵀa). Pour a=(1,1) et b=(2,0), c=1, p=(1,1) et le résidu e=(1,−1) est perpendiculaire à la droite. La matrice P=aaᵀ/(aᵀa) vérifie Pᵀ=P et P²=P. Pour un sous-espace de base donnée par les colonnes indépendantes de A, la formule devient P=A(AᵀA)⁻¹Aᵀ. La condition d’indépendance garantit que cette inverse existe . La projection géométrique reste définie même avec une liste génératrice redondante. Changer l’échelle de a ne change pas la droite ni la projection.",
