            Exercise.MultipleChoice(id = "mit_18_06sc_2011_s032_e03", prompt = "L’élimination EA=U conserve-t-elle forcément les valeurs propres de A ?", options = listOf("Oui, si les nombres sont réels.", "Non ; une multiplication à gauche seule n’est généralement pas une similarité.", "Oui, toute opération de ligne conserve le spectre.", "Oui, car E est inversible."), correctOptionIndex = 1, explanation = "L’inversibilité de E conserve le rang mais pas le spectre. Une similarité demande les deux facteurs S⁻¹ et S.", hint = "Distinguer équivalence de systèmes et changement de base.")
